use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-g2-prefix-tree";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let mut plan=read("/tmp/zopro-isolated-grouping/native-plan.json");let text=serde_json::to_string(&plan).unwrap().replace("/tmp/zopro-isolated-grouping",R).replace("--cfg zopro_isolated_grouping","--cfg zopro_g2_level_tree --cfg zopro_g2_prefix_tree");plan=serde_json::from_str(&text).unwrap();plan["environment"].as_object_mut().unwrap().remove("ZOPRO_CPU_GROUPING_LOWER_BOUND");for step in plan["steps"].as_array_mut().unwrap(){if step["name"]=="on-core"{step["required_tests"]=json!(["msm_affine::g2_level_tree::tests::complete_query_matches_generator_oracle_across_workers","msm_affine::g2_level_tree::tests::actual_size_random_query_matches_independent_generator_sum","msm_affine::g2_level_tree::tests::checked_forecast_covers_empty_and_boundary_and_rejects_geometry","msm_affine::g2_prefix_tree::tests::prefix_query_complete_curve_generator_oracles","msm_affine::g2_prefix_tree::tests::actual_size_prefix_matches_stream_and_generator","msm_affine::g2_prefix_tree::tests::prefix_forecast_and_geometry_are_checked","msm::g2_prefix_tree_tests::grouped_prefix_handles_signed_exceptions_odd_and_skewed_buckets","msm::g2_prefix_tree_tests::prefix_group_cost_rejects_overflow"]);}if step["kind"]=="link-sdk"{step["driver"]=json!(r.join("probe.rs"));step["additional_sources"]=json!([r.join("support/perf.rs")]);}}
 let base=read("/tmp/zopro-prefix-pool/perf-plan.json");let old=read("/tmp/zopro-opposite-scalar-census/cases.json");let mut cases=Vec::new();for c in old.as_array().unwrap().iter().filter(|c|["1x2","2x2"].contains(&c["shape"].as_str().unwrap())){let mut c=c.clone();c["image"]=base["cases"].as_array().unwrap().iter().find(|x|x["shape"]==c["shape"]).unwrap()["image"].clone();cases.push(c);}assert_eq!(cases.len(),2);save(r.join("cases.json"),&json!(cases));let manifest=read("/tmp/zopro-grouping-module/production-source-manifest.json");let mut pins=BTreeMap::new();let mut changed=Vec::new();for(rel,h)in manifest["source_files_sha256"].as_object().unwrap(){let p=r.join("candidate").join(rel);let actual=hash(&p);if actual!=h.as_str().unwrap(){changed.push(rel.clone());}pins.insert(p.display().to_string(),actual);}assert_eq!(changed.len(),5);for rel in ["candidate/crates/zopro-core/src/msm_affine/g2_level_tree.rs","candidate/crates/zopro-core/src/msm_affine/g2_prefix_tree.rs","adapt.rs","analyze.inc.rs","probe.rs","support/perf.rs","design.md","setup.rs","run.rs","closeout.rs","cases.json"]{let p=r.join(rel);pins.insert(p.display().to_string(),hash(&p));}for c in &cases{for key in ["key","image","request"]{let p=c[key].as_str().unwrap();pins.insert(p.into(),hash(p));}}save(r.join("source-pins.json"),&json!(pins));save(r.join("source-audit.json"),&json!({"changed_originals":changed,"new_modules":["msm_affine/g2_level_tree.rs","msm_affine/g2_prefix_tree.rs"],"original_sources":170,"production_unchanged":true,"SDK_dispatch_unchanged":true}));save(r.join("native-plan.json"),&plan);
}
